changeSet.sql:

alter table workflow.ItemAssignment add ItemStepID bigint null;
go

update A
set A.ItemStepID = IST.ID
from workflow.ItemAssignment A
inner join workflow.ItemStep IST on IST.StepID = A.StepID and IST.ItemID = A.ItemID;
go

alter table workflow.ItemAssignment drop column StepID;
go

changeSet.rollback:

alter table workflow.ItemAssignment add StepID int null;
go
update A
set A.StepID = IST.StepID
from workflow.ItemAssignment A
inner join workflow.ItemStep IST on IST.ID = A.ItemStepID;
go
alter table workflow.ItemAssignment drop column ItemStepID;
go
